{"path": "task/workspace/app/meta.go", "start": 1, "lines": 33, "offset": 0, "total_lines": 33, "content": "package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metaMutex sync.RWMutex
	metadata  = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata sets the application metadata that will be returned by calls to app.Metadata().
// This is typically set at build time to embed version information into the application.
//
// Since: 2.2
func SetMetadata(m fyne.AppMetadata) {
	metaMutex.Lock()
	defer metaMutex.Unlock()
	metadata = m
}

func getMetadata() fyne.AppMetadata {
	metaMutex.RLock()
	defer metaMutex.RUnlock()
	return metadata
}
